import { Injectable } from '@angular/core';
import { make } from '../pages/make/make';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class MakeService {
  private apiUrl = `${environment.apiUrl}/make`; 
  constructor(private http: HttpClient) {}

  getAllProducts(): Observable<make[]> {
    return this.http.get<make[]>(this.apiUrl);
  }
  getProductByID(id: number): Observable<make> {
    return this.http.get<make>(`${this.apiUrl}/${id}`)
  }
  addProduct(product: make): Observable<make> {
  return this.http.post<make>(`${this.apiUrl}/create`, product);
}

updateProduct(id: number, product: make): Observable<make> {
  return this.http.put<make>(`${this.apiUrl}/update/${id}`, product);
}

deleteProduct(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
